import { fireEvent, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { BotTurnEndedEventInfo } from "./BotTurnEndedEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

const baseEvent: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.BotTurnEnded,
  name: "bot_turn_ended",
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    parseData: {},
  },
};

describe("BotTurnEndedEventInfo", () => {
  it("renders the title", () => {
    renderWithProviders(<BotTurnEndedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.getByText("Agent turn ended")).toBeInTheDocument();
  });

  it("calls onClose when close button is clicked", () => {
    const onClose = vi.fn();
    renderWithProviders(<BotTurnEndedEventInfo event={baseEvent} onClose={onClose} />);

    fireEvent.click(screen.getByTestId("event-details-close"));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("renders the event details accordion section", () => {
    renderWithProviders(<BotTurnEndedEventInfo event={baseEvent} onClose={vi.fn()} />);

    expect(screen.getByText("Event details")).toBeInTheDocument();
  });

  describe("latency section", () => {
    it("shows latency accordion when latency_breakdown is present", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          latency_breakdown: { user_perceived_latency_ms: 350 },
        },
      };

      renderWithProviders(<BotTurnEndedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("User-perceived latency")).toBeInTheDocument();
    });

    it("shows latency pill from user_perceived_latency_ms", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          latency_breakdown: { user_perceived_latency_ms: 350 },
        },
      };

      renderWithProviders(<BotTurnEndedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("~350 ms")).toBeInTheDocument();
    });

    it("shows all latency_breakdown rows when fully populated", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          latency_breakdown: {
            user_perceived_latency_ms: 500,
            command_generator_ms: 100,
            first_agent_response: {
              llm_time_to_first_token_ms: 200,
              llm_total_generation_ms: 300,
              generated_by_llm: true,
            },
            first_voice_response: {
              tts_time_to_first_byte_ms: 50,
              tts_total_generation_ms: 80,
              read_from_cache: false,
            },
            full_turn: { prediction_loop_ms: 400 },
          },
        },
      };

      renderWithProviders(<BotTurnEndedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.getByText("Command processor:")).toBeInTheDocument();
      expect(screen.getByText("Time to first LLM token:")).toBeInTheDocument();
      expect(screen.getByText("Time to first byte:")).toBeInTheDocument();
      expect(screen.getByText("LLM total generation:")).toBeInTheDocument();
      expect(screen.getByText("TTS total generation:")).toBeInTheDocument();
      expect(screen.getByText("TTS from cache:")).toBeInTheDocument();
      expect(screen.getByText("Total bot turn time:")).toBeInTheDocument();
    });

    it("does not show latency section when no latency data is present", () => {
      renderWithProviders(<BotTurnEndedEventInfo event={baseEvent} onClose={vi.fn()} />);

      expect(screen.queryByText("User-perceived latency")).not.toBeInTheDocument();
    });

    it("does not show latency section when latency_breakdown is undefined", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: {
          ...baseEvent.metadata,
          latency_breakdown: undefined,
        },
      };

      renderWithProviders(<BotTurnEndedEventInfo event={event} onClose={vi.fn()} />);

      expect(screen.queryByText("User-perceived latency")).not.toBeInTheDocument();
    });
  });
});
